INSERT INTO public.editorial_content (id,content_type,title,subtitle,summary,body,publish_date,author_name,eligible_for_daily,status) VALUES ('b1082026-1008-4a91-8d62-000000000070','article','Conoce La Paz','El Porvenir, sus titulares y su patrimonio','Una lectura de la Hermandad de la Paz a través de su historia, sus imágenes y su música.','La Paz nació en 1939 en El Porvenir, impulsada por jóvenes vinculados al Parque Farmacéutico del Ejército. La idea de una cofradía atravesando María Luisa se hizo realidad el Domingo de Ramos de 1940.
